    cnt=Ct(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; rects=[]
    for r0 in range(H):
        for c0 in range(W):
            if seen[r0][c0]: continue
            c=g[r0][c0]
            if c==bg: continue
            r=r0; cc=c0
            while r+1<H and g[r+1][cc]==c: r+=1
            while cc+1<W and g[r0][cc+1]==c: cc+=1
            if (r-r0+1)*(cc-c0+1)<4: 
                seen[r0][c0]=True; continue
            for a in range(r0,r+1):
                for b in range(c0,cc+1): seen[a][b]=True
            rects.append((r0,c0,r,cc,c,(r-r0+1)*(cc-c0+1)))
    out=[list(row) for row in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v==bg: continue
            hits=[k for k,(r0,c0,rr,ccc,c,sz) in enumerate(rects) if r0<=i<=rr and c0<=j<=ccc]
            if hits:
                k=max(hits,key=lambda k:rects[k][5]); out[i][j]=rects[k][4]; continue
            def gap(rr,ccc,i,j):
                dr=max(rr-i,i-rr,0); dc=max(ccc-j,j-ccc,0); return max(dr,dc)
            best=min(((gap(*r[0:4],i,j), -r[5], r[4]) for r in rects))
            out[i][j]=best[2]
    return out
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    p=solve5(G[name+' input']); o=G[name+' output']
    bad=[(i,j,p[i][j],o[i][j]) for i in range(len(o)) for j in range(len(o[0])) if p[i][j]!=o[i][j]]
    print(name,'match:',p==o,'nmis:',len(bad),bad[:6])

