def solve7(g):
    H,W=len(g),len(g[0])
    cnt=Ct(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; rects=[]; cmap={}
    for r0 in range(H):
        for c0 in range(W):
            if seen[r0][c0]: continue
            c=g[r0][c0]
            if c==bg: continue
            r=r0; cc=c0
            while r+1<H and g[r+1][cc]==c: r+=1
            while cc+1<W and g[r0][cc+1]==c: cc+=1
            if (r-r0+1)*(cc-c0+1)<4: 
                seen[r0][c0]=True; continue
            for a in range(r0,r+1):
                for b in range(c0,cc+1): seen[a][b]=True
            for a in range(r0,r+1):
                for b in range(c0,cc+1): cmap[(a,b)]=c
            rects.append((r0,c0,r,cc,c))
    out=[list(row) for row in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v==bg: continue
            if (i,j) in cmap:
                out[i][j]=cmap[(i,j)]; continue
            # nearest rect cell by Manhattan (through empty space?) — try direct Chebyshev to any rect cell
            def dist2(cr):
                rr,ccc=cr[:2]
                return max(abs(i-rr),abs(j-ccc))
            best=min(rects,key=lambda rec:dist2(rec))
            out[i][j]=best[4]
    return out
