def solve8(g):
    H,W=len(g),len(g[0])
    cnt=Ct(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    # connected components (4-conn)
    seen=[[False]*W for _ in range(H)]; comps=[]
    for r0 in range(H):
        for c0 in range(W):
            if seen[r0][c0]: continue
            st=[(r0,c0)]; seen[r0][c0]=True; cells=[]
            while st:
                a,b=st.pop(); cells.append((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==g[a][b]:
                            seen[na][nb]=True; st.append((na,nb))
            comps.append(cells)
    rects=[]; noise=set()
    for cells in comps:
        rs=[a for a,_ in cells]; cs=[b for _,b in cells]
        h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
        area=len(cells)
        if area>=h*w*0.75 and h*w>=4:   # nearly solid rectangle
            r0=min(rs); c0=min(cs); rr=max(rs); ccc=max(cs)
            rects.append((r0,c0,rr,ccc,g[r0][c0],area))
        else:
            noise.update(cells)
    out=[list(row) for row in g]
    for i,j in noise:
        hits=[k for k,(r0,c0,rr,ccc,_,_) in enumerate(rects) if r0<=i<=rr and c0<=j<=ccc]
        if hits:
            k=min(hits,key=lambda k:rects[k][:4])  # top-leftmost containing rect
            out[i][j]=rects[k][4]
        else:
            out[i][j]=bg
    return out
