    p=solve8(G[name+' input']); o=G[name+' output']
    bad=[(i,j,p[i][j],o[i][j]) for i in range(len(o)) for j in range(len(o[0])) if p[i][j]!=o[i][j]]
    print(name,'match:',p==o,'nmis:',len(bad),bad[:6])

def solve9(g):
    H,W=len(g),len(g[0])
    cnt=Ct(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; rects=[]
    for r0 in range(H):
        for c0 in range(W):
            if seen[r0][c0]: continue
            st=[(r0,c0)]; seen[r0][c0]=True; cells=set()
            while st:
                a,b=st.pop(); cells.add((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not (na,nb) in cells and g[na][nb]==g[a][b]:
                            seen[na][nb]=True; st.append((na,nb))
            rs=[a for a,_ in cells]; cs=[b for _,b in cells]
            h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
            if h*w>=4 and len(cells)/h/w>=0.85:
                r0=min(rs); c0=min(cs); rr=max(rs); ccc=max(cs)
                rects.append((r0,c0,rr,ccc,g[r0][c0],h*w)); 
                # skip interior non-majority as separate seed
            else:
                for a,b in cells: seen[a][b]=True
                continue
            for a,b in cells: seen[a][b]=True
    out=[list(row) for row in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v==bg: continue
            hits=[k for k,(r0,c0,rr,ccc,c,sz) in enumerate(rects) if r0<=i<=rr and c0<=j<=ccc]
            if hits:
                k=max(hits,key=lambda k:rects[k][5]); out[i][j]=rects[k][4]; continue
            out[i][j]=bg
    return out
