def solve11(g):
    H,W=len(g),len(g[0])
    cnt=Ct(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; rects=[]
    for r0 in range(H):
        for c0 in range(W):
            if seen[r0][c0]: continue
            st=[(r0,c0)]; seen[r0][c0]=True; cells=[]
            while st:
                a,b=st.pop(); cells.append((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and (na,nb) not in set(cells) and g[na][nb]==g[a][b]:
                            seen[na][nb]=True; st.append((na,nb))
            rs=[a for a,_ in cells]; cs=[b for _,b in cells]
            h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
            if len(cells)/(h*w)>=0.6 and h*w>=4:
                rects.append((min(rs),min(cs),max(rs),max(cs),g[r0][c0],h*w,len(cells)))
                for a,b in cells: seen[a][b]=True
            else:
                for a,b in cells: seen[a][b]=True
    out=[list(row) for row in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v==bg: continue
            hits=[k for k,(r0,c0,rr,ccc,c,sz,n) in enumerate(rects) if r0<=i<=rr and c0<=j<=ccc]
            if hits:
                # prefer smallest rect among those containing cell, tie larger area
                k=min(hits,key=lambda k:rects[k][5])
                out[i][j]=rects[k][4]; continue
            out[i][j]=bg
    return out
